predicate isStrangeSorted(s: seq<int>)
    reads s
{
    var n := |s|;
    if n == 0 {
        return true; // an empty list is trivially strange sorted
    }

    var minIndex := 0;
    var maxIndex := n - 1;
    var expectMin := true;

    var i := 0;
    while i < n
        invariant 0 <= i <= n
        invariant minIndex <= maxIndex
    {
        if expectMin {
            // Expecting the minimum
            if s[i] != Min(s[minIndex..maxIndex + 1]) {
                return false; // not the expected minimum
            }
            minIndex := minIndex + 1; // move past the minimum found
            expectMin := false; // next we expect maximum
        } else {
            // Expecting the maximum
            if s[i] != Max(s[minIndex..maxIndex + 1]) {
                return false; // not the expected maximum
            }
            maxIndex := maxIndex - 1; // move past the maximum found
            expectMin := true; // next we expect minimum
        }
        i := i + 1;
    }
    return true; // the list satisfies the strange sorting order
}
